CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS objects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, name TEXT NOT NULL, country TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, height_m DOUBLE PRECISION, object_type TEXT NOT NULL CHECK (object_type IN ('B','A','S','E','Other')), object_type_other TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((object_type <> 'Other') OR (length(trim(coalesce(object_type_other,''))) > 0)));
CREATE TABLE IF NOT EXISTS gear_presets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, name TEXT NOT NULL, rig TEXT, suit TEXT, pilot_chute TEXT, slider_configuration TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jumps (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, jump_number BIGINT NOT NULL, object_id UUID REFERENCES objects(id) ON DELETE SET NULL, object_name TEXT, country TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, date_time TIMESTAMPTZ, height_m DOUBLE PRECISION, object_type TEXT CHECK (object_type IN ('B','A','S','E','Other')), object_type_other TEXT, slider_configuration TEXT, pilot_chute TEXT, suit TEXT, summit_osp TEXT, rig TEXT, jump_type TEXT, wind_strength DOUBLE PRECISION, wind_direction TEXT, delay_seconds DOUBLE PRECISION, delay_for_su_seconds DOUBLE PRECISION, exit_manoeuvre TEXT, off_heading BOOLEAN, correction BOOLEAN, brake_setting TEXT, sky_cover TEXT, lighting TEXT, private_notes TEXT, beautiful_people_around TEXT, deployment_method TEXT, opening_direction_degrees INTEGER, opening_direction_side TEXT, flysight_track JSONB, extra_fields JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, jump_number), CHECK ((object_type IS DISTINCT FROM 'Other') OR (length(trim(coalesce(object_type_other,''))) > 0)));
CREATE TABLE IF NOT EXISTS jump_media (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, jump_id UUID NOT NULL REFERENCES jumps(id) ON DELETE CASCADE, storage_key TEXT NOT NULL, media_type TEXT NOT NULL CHECK (media_type IN ('photo','video','track')), file_name TEXT NOT NULL, mime_type TEXT, size_bytes BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS custom_options (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, field_key TEXT NOT NULL, label TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, field_key, label));
CREATE INDEX IF NOT EXISTS jumps_user_datetime_idx ON jumps(user_id, date_time DESC);
CREATE INDEX IF NOT EXISTS jumps_user_object_idx ON jumps(user_id, object_id);
CREATE INDEX IF NOT EXISTS objects_user_name_idx ON objects(user_id, name);
CREATE INDEX IF NOT EXISTS gear_presets_user_name_idx ON gear_presets(user_id, name);
CREATE INDEX IF NOT EXISTS jump_media_user_jump_idx ON jump_media(user_id, jump_id);
